#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("ciag.txt");
    vector<int> dane;
    int x;
    while (plik >> x) dane.push_back(x);
    int cnt = 0, curLen = 1;
    for (int i = 1; i < (int)dane.size(); i++) {
        if (dane[i] > dane[i - 1]) {
            curLen++;
        } else {
            if (curLen >= 3) cnt++;
            curLen = 1;
        }
    }
    if (curLen >= 3) cnt++;
    cout << "Ciagi rosnace dlugosci >= 3: " << cnt << endl;
    return 0;
}
```

